from pathlib import Path
import html, json
p = Path(__file__).parent
m = json.loads((p / 'messages.json').read_text(encoding='utf-8-sig'))
letter = ''.join('<p>' + html.escape(paragraph) + '</p>' for paragraph in m['letter'].split('\n\n'))
# Each stem and flower is timed individually, like a pen building a bouquet.
flowers = [(160,236,-27,'pink'),(221,171,-17,'gold'),(277,127,-7,'rose'),(338,105,2,'gold'),(398,140,12,'pink'),(456,180,22,'gold'),(505,236,31,'rose'),(244,246,-14,'pink'),(346,208,4,'rose'),(432,246,17,'gold')]
stems, blooms = [], []
for i,(x,y,angle,color) in enumerate(flowers):
 delay = .35 + i*.21
 stems.append(f'<path class="stem" style="--delay:{delay:.2f}s" d="M 335 576 Q {335+(x-335)*.5:.0f} 408 {x} {y+54}"/>')
 blooms.append(f'<g class="bloom" style="--delay:{delay+1.05:.2f}s" transform="translate({x} {y}) rotate({angle})"><g class="bloom-inner"><path class="petal-back {color}" d="M0 58 C-31 51 -39 15 -28 -22 Q-15 -17 0 -2 Q15 -17 28 -22 C39 15 31 51 0 58Z"/><path class="petal-left {color}" d="M0 58 C-30 53 -39 25 -30 -14 C-18 -10 -4 9 0 58Z"/><path class="petal-right {color}" d="M0 58 C30 53 39 25 30 -14 C18 -10 4 9 0 58Z"/><path class="petal-line" d="M0 54 Q-12 21 -17 2 M0 54 Q12 21 17 2"/></g></g>')
svg = '''<svg class="bouquet" viewBox="0 0 670 760" role="img" aria-label="Pink and yellow tulips slowly forming a bouquet"><defs><linearGradient id="paper" x2="1" y2="1"><stop stop-color="#fff8ef"/><stop offset="1" stop-color="#edc6c5"/></linearGradient><linearGradient id="pink" x2=".8" y2="1"><stop stop-color="#ffd0d8"/><stop offset="1" stop-color="#d97997"/></linearGradient><linearGradient id="rose" x2=".8" y2="1"><stop stop-color="#f9b9cb"/><stop offset="1" stop-color="#c76589"/></linearGradient><linearGradient id="gold" x2=".8" y2="1"><stop stop-color="#fff1ad"/><stop offset="1" stop-color="#e6aa48"/></linearGradient><filter id="shadow" x="-40%" y="-40%" width="180%" height="180%"><feDropShadow dx="0" dy="16" stdDeviation="17" flood-color="#9a6b73" flood-opacity=".2"/></filter></defs><ellipse cx="335" cy="716" rx="157" ry="16" fill="#9c6575" opacity=".08"/><g filter="url(#shadow)"><g class="wrap-back"><path d="M108 325 Q235 354 335 365 Q442 355 562 325 L388 664 Q335 690 280 664Z" fill="#f5dfdb" stroke="#e7c3c3" stroke-width="2"/><path d="M108 325 Q192 350 270 400 L335 647 Q220 480 108 325Z" fill="#fff8f1" opacity=".7"/><path d="M562 325 Q483 355 400 400 L335 647 Q452 480 562 325Z" fill="#eac4c7" opacity=".55"/></g><g class="stems">STEMS</g><g class="leaves"><path d="M319 562 Q216 466 185 348 Q275 399 330 548Z"/><path d="M345 559 Q443 448 480 337 Q393 386 335 547Z"/><path d="M325 567 Q256 489 252 381 Q312 437 336 556Z"/><path d="M345 560 Q399 479 407 375 Q351 437 330 555Z"/></g>BLOOMS<g class="wrap-front"><path d="M112 330 Q221 394 334 457 Q448 395 558 330 L385 660 Q334 686 283 660Z" fill="url(#paper)" stroke="#e4bfc0" stroke-width="2"/><path d="M112 330 Q223 397 334 457 L283 660Z" fill="#fff9f3" opacity=".48"/><path d="M558 330 Q447 397 334 457 L385 660Z" fill="#ddaeb6" opacity=".22"/><path d="M334 457 L334 651" stroke="#d7aeb2" opacity=".55"/><path d="M302 579 Q335 593 368 579 L371 597 Q335 611 299 597Z" fill="#c77e91"/><path d="M333 590 C296 553 278 573 294 593 C305 606 322 599 333 594 C344 599 361 606 374 593 C389 574 371 553 333 590Z" fill="#d99bab" stroke="#bd778d" stroke-width="2"/><circle cx="333" cy="591" r="7" fill="#b86c83"/><path d="M327 596 Q310 626 299 632 M340 596 Q354 620 368 626" fill="none" stroke="#c78094" stroke-width="9" stroke-linecap="round"/></g></g></svg>'''.replace('STEMS',''.join(stems)).replace('BLOOMS',''.join(blooms))
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f9e8ed"><title>For Miss Nurse</title><link rel="stylesheet" href="style.css"></head><body><button class="letter-button" id="open-letter" aria-label="Open letter" title="Open letter"><svg viewBox="0 0 32 32" aria-hidden="true"><rect x="3" y="7" width="26" height="19" rx="3"/><path d="m4 9 12 9L28 9"/><path d="M14 19c-3-3 1-5 2-2 1-3 5-1 2 2l-2 2z"/></svg></button><div class="fireworks" aria-hidden="true"><i></i><i></i><i></i></div><main><div class="scene">BOUQUET</div></main><dialog id="letter" aria-label="Letter for Miss Nurse"><button id="close-letter" aria-label="Close letter">×</button><div class="letter-content">LETTER<p class="signature">With love ♡</p></div></dialog><script src="script.js"></script></body></html>'''.replace('BOUQUET',svg).replace('LETTER',letter)
(p / 'index.html').write_text(page,encoding='utf-8')
